INSERT INTO `heroes` (`id`, `badge`, `title`, `subtitle`, `image`, `created_at`, `updated_at`) VALUES
(1, '🥭 আসল ঘরোয়া স্বাদের Desi Achar Combo', 'খাঁটি সিরাজগঞ্জ লুঙ্গির ঐতিহ্য, প্রিমিয়াম কমফোর্টে', '৩ রকমের প্রিমিয়াম আচার — আম, মিক্সড ভেজ, নিম্বু। ছোট ব্যাচে তৈরি, কোনো প্রিজারভেটিভ নেই।', '1781025320-hero.jpg', '2025-12-08 00:31:06', '2026-06-09 11:15:20');
